'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const museums=[...GUANWU.museums,...GUANWU_EXPANSION.museums,...GUANWU_CITY_MUSEUMS.museums,...GUANWU_BEIJING_MUSEUMS.museums],crafts=GUANWU.crafts,artifacts=GUANWU_EXPANSION.artifacts;
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('浏览器存储暂不可用，本次记录可能无法保留。')}}
const state={city:stored('guanwu-city-v2','全部'),category:'全部',museumKind:'全部',district:'全部',query:'',saved:stored('guanwu-saved-v2',[]),notes:stored('guanwu-notes-v2',{}),plan:stored('guanwu-plan-v2',[]),dates:stored('guanwu-dates-v2',{}),stamps:stored('guanwu-stamps-v2',[]),member:stored('guanwu-demo-member',false),hero:0,gallery:null,downloadBusy:false};
let images={},toastTimer,previousRoute='';
function photo(id,extra=''){if(!id)return '<span class="museum-photo-placeholder">馆舍影像待补充</span>';return `<img src="${images[id]?.src||`assets/heritage/${id}.jpg`}" alt="${esc(images[id]?.caption||id)}" ${extra}>`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function dialog(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function title(en,name,sub){return `<div class="intro"><div><div class="eyebrow">${en}</div><h1>${name}</h1><p>${sub}</p></div><div class="date-note">看见手艺，听见城市。</div></div>`}
function head(name,en,href,label){return `<div class="section-head"><div class="section-title"><h2>${name}</h2><span>${en}</span></div>${href?`<a class="text-link" href="${href}">${label} ${icon('arrow')}</a>`:''}</div>`}
function cityTabs(){return `<div class="city-tabs" aria-label="城市筛选">${['全部',...new Set(museums.map(m=>m.city))].map(c=>`<button class="city-chip ${state.city===c?'active':''}" data-city="${c}" aria-pressed="${state.city===c}">${c}${c!=='全部'?`<small>${museums.filter(m=>m.city===c).length.toString().padStart(2,'0')}</small>`:''}</button>`).join('')}</div>`}
function districtPicker(){if(state.city!=='北京')return '';const districts=[...new Set(museums.filter(m=>m.city==='北京').map(m=>m.district).filter(Boolean))];return `<div class="district-filter"><label for="museum-district">按城区找馆</label><select id="museum-district"><option value="全部">北京 · 全部城区</option>${districts.map(d=>`<option value="${esc(d)}" ${state.district===d?'selected':''}>${esc(d)}</option>`).join('')}</select><span>50 家馆，从附近或兴趣开始。</span></div>`}
function museumGroup(m){const text=[m.kind,...m.tags].join('');return /自然|科学|科技|地质|天文|农业|古动物/.test(text)?'自然科学':/遗址|考古|商都/.test(text)?'遗址考古':/丝绸|纺织|工艺|艺术|美术|非遗|云锦|织绣|御窑/.test(text)?'工艺艺术':/历史|综合/.test(text)?'历史综合':'城市专题'}
function filteredMuseums(){return museums.filter(m=>(!state.museumKind||state.museumKind==='全部'||museumGroup(m)===state.museumKind)&&(state.city==='全部'||m.city===state.city)&&(state.district==='全部'||m.district===state.district)&&(!state.query||[m.name,m.city,m.district||'',m.kind,...m.tags].join('').includes(state.query)))}
function filteredCrafts(){return crafts.filter(c=>(state.city==='全部'||c.city===state.city)&&(state.category==='全部'||c.category===state.category)&&(!state.query||[c.title,c.category,c.city,c.intro].join('').includes(state.query)))}
function saveButton(key,cls='save-btn'){const yes=state.saved.includes(key);return `<button class="${cls} ${yes?'saved':''}" data-save="${key}" aria-pressed="${yes}" aria-label="${yes?'取消收藏':'收藏'}">${icon('heart')}</button>`}
function museumCard(m){return `<article class="museum-card"><a class="museum-cover" href="#museum/${m.id}">${photo(m.cover,'loading="lazy"')}<span class="museum-city">${m.roman} · ${m.city}</span><span class="museum-kind">${m.highlights?.length?'新收录 · ':''}${m.kind}</span></a>${saveButton('museum:'+m.id)}<div class="museum-card-copy"><div class="museum-overline">${m.tags.slice(0,2).join(' / ')}</div><h3><a href="#museum/${m.id}">${m.name}</a></h3><p>${m.theme}</p><div class="museum-card-foot"><span>${m.chapters[0]?.audio===false?'文物观察手记':'◉ 3 章语音导览'}</span><span>${m.duration} ↗</span></div></div></article>`}
function craftCard(c){return `<article class="craft-card"><a class="craft-cover" href="#craft/${c.id}">${photo(c.cover,'loading="lazy"')}<span class="badge">${c.city} · ${c.category}</span></a>${saveButton('craft:'+c.id)}<h3><a href="#craft/${c.id}">${c.title}</a></h3><p>${c.intro}</p><small>${c.label}<span>◉ 听讲解</span></small></article>`}
function hero(){const m=museums[state.hero];return `<section class="hero heritage-hero" aria-label="精选场馆：${m.name}">${photo(m.cover,'fetchpriority="high"')}<div class="hero-content"><div class="hero-kicker">城市博物馆计划 · ${m.city}站</div><h2>一座城，<br>一双手的记忆。</h2><p>${m.name}<br>${m.theme}</p><a class="hero-cta" href="#museum/${m.id}">走近这座馆 ${icon('arrow')}</a></div><div class="hero-controls"><div class="hero-dots" aria-label="切换精选城市">${museums.map((v,i)=>`<button data-hero="${i}" aria-label="查看${v.city}精选" aria-pressed="${i===state.hero}" class="${i===state.hero?'active':''}"></button>`).join('')}</div><span><b>${String(state.hero+1).padStart(2,'0')}</b> / ${museums.length}</span><button data-hero="${(state.hero+1)%museums.length}" aria-label="下一个城市">→</button></div><button class="hero-credit" data-gallery="museum:${m.id}:0">影像来源 ↗</button></section>`}
function home(){return GuanwuExperience.home()}
function collection(){return `${title('THE MUSEUM ATLAS','把博物馆，装进行囊',`${new Set(museums.map(m=>m.city)).size} 城 ${museums.length} 馆 · ${artifacts.length} 件文物与 ${crafts.length} 门手艺`)}${cityTabs()}${districtPicker()}<form id="search-form" class="search-box"><input id="collection-search" type="search" value="${esc(state.query)}" placeholder="搜索城市、场馆、文物或手艺" aria-label="搜索城市、场馆或手艺"><button class="solid-btn">搜索</button></form><div class="museum-kind-filters" aria-label="按主题选馆">${['全部','历史综合','工艺艺术','遗址考古','城市专题','自然科学'].map(k=>`<button data-museum-kind="${k}" class="${state.museumKind===k?'active':''}" aria-pressed="${state.museumKind===k}">${k}</button>`).join('')}</div><div id="search-results">${searchResults()}</div>`}
function filteredArtifacts(){return artifacts.filter(a=>(state.city==='全部'||a.city===state.city)&&(!state.query||[a.title,a.city,a.period,a.material,a.intro].join('').includes(state.query)))}
function artifactCard(a){return `<article class="craft-card"><a class="craft-cover" href="#artifact/${a.id}">${photo(a.cover,'loading="lazy"')}<span class="badge">${a.city} · ${a.period}</span></a>${saveButton('artifact:'+a.id)}<h3><a href="#artifact/${a.id}">${a.title}</a></h3><p>${a.intro}</p><small>${a.material}<span>细看文物 ↗</span></small></article>`}
function artifactSection(items=filteredArtifacts()){return items.length?`<section class="section">${head('与文物相遇',items.length+' OBJECTS')}<div class="craft-grid">${items.map(artifactCard).join('')}</div></section>`:''}
function searchResults(){const cityOrder=[...new Set(museums.map(m=>m.city))],ms=filteredMuseums().sort((a,b)=>cityOrder.indexOf(a.city)-cityOrder.indexOf(b.city)||Number(!!b.highlights?.length)-Number(!!a.highlights?.length)),cs=filteredCrafts(),aa=filteredArtifacts();return ms.length||cs.length||aa.length?`${ms.length?`${head('博物馆',ms.length+' MUSEUMS')}<p class="museum-results-note">${state.city==='全部'?'每座城市，至少三家馆可选。':'在'+state.city+'，找到不同的观看入口。'}先选馆看重点，或到<a href="#journeys">城市漫游</a>组合一次参观。</p><div class="museum-grid">${ms.map(museumCard).join('')}</div>`:''}${artifactSection(aa)}${cs.length?`<section class="section">${head('相关手艺',cs.length+' CRAFT STORIES')}<div class="craft-grid">${cs.map(craftCard).join('')}</div></section>`:''}`:empty('暂时没有找到这段故事','试试城市、场馆或文物名称，也可以重新浏览全部内容。')}
function craftsPage(){return `${title('THE ART OF MAKING','手艺的微小宇宙','从材料、动作和纹样出发，找到自己的观看方法。')}${cityTabs()}<div class="filter-row">${['全部','金工','织绣','戏曲','民俗'].map(c=>`<button class="pill ${c===state.category?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="craft-grid">${filteredCrafts().map(craftCard).join('')}</div>`}
function empty(name,sub){return `<div class="empty"><h2>${name}</h2><p>${sub}</p><button class="solid-btn" data-action="reset-search">重新发现 →</button></div>`}
function breadcrumbs(text){return `<div class="detail-breadcrumb"><a href="#collection">博物馆</a><span>/</span>${esc(text)}</div>`}
function galleryStrip(kind,item){return `<div class="gallery-strip">${item.gallery.slice(0,5).map((id,i)=>`<button data-gallery="${kind}:${item.id}:${i}" aria-label="放大图片 ${i+1}：${esc(images[id]?.caption)}">${photo(id,'loading="lazy"')}${i===item.gallery.length-1?'<span>查看大图 ↗</span>':''}</button>`).join('')}</div>`}
function sourceLinks(items){return `<div class="evidence-links">${items.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('')}</div>`}
function notePanel(key){return `<section class="note-panel"><div class="section-title"><h2>留一句自己的发现</h2><span>FIELD NOTES</span></div><label class="sr-only" for="note-input">参观手记</label><textarea id="note-input" data-note="${key}" maxlength="800" placeholder="今天留住你的，是一条线、一种颜色，还是一个声音？">${esc(state.notes[key]||'')}</textarea><div><small id="note-status">保存在当前浏览器 · 最多 800 字</small><button class="text-link" data-action="save-note" data-id="${key}">保存手记 ↗</button></div></section>`}
function museumPage(id){const m=museums.find(m=>m.id===id);if(!m)return missing();return `${breadcrumbs(m.city)}<div class="museum-heading"><div><div class="eyebrow">${m.roman} · ${m.kind}</div><h1>${m.name}</h1><p>${m.quote}</p></div><div class="heading-buttons">${saveButton('museum:'+id,'round-btn')}<button class="round-btn" data-action="share" aria-label="复制分享链接">↗</button></div></div><div class="museum-detail-grid"><div class="museum-visual"><button class="museum-main-image" ${m.gallery.length?`data-gallery="museum:${id}:0"`:'disabled'} aria-label="放大${m.name}图片">${photo(m.cover)}<span>${m.gallery.length?`查看 ${m.gallery.length} 张图片 ↗`:'馆舍照片待补充'}</span></button>${galleryStrip('museum',m)}<p class="photo-note">${esc(images[m.cover]?.caption||'暂无可复用馆舍照片')} · <button data-action="credits">摄影与许可 ↗</button></p></div><div class="visit-card"><div class="eyebrow">YOUR FIRST VISIT</div><h2>${m.theme}</h2><p>${m.intro}</p><div class="visit-address">${icon('pin')}<span>${m.address}</span></div><div class="visit-facts"><span>${m.duration}</span><span>${m.chapters[0]?.audio===false?'3 章阅读手记':'3 章导览 · 普通话'}</span></div>${m.chapters[0]?.audio===false?`<button class="solid-btn full" data-action="transcript" data-id="${id}">读一读这座馆 →</button>`:`<button class="solid-btn full" data-play="museum:${id}:0">▷ 听一听这座馆</button>`}<button class="outline-btn full" data-plan="${id}">${state.plan.includes(id)?'✓ 已加入行程 · 点击移除':'＋ 加入我的行程'}</button><div class="visit-links"><a href="https://uri.amap.com/search?keyword=${encodeURIComponent(m.fullName)}&city=${encodeURIComponent(m.city)}&callnative=0" target="_blank" rel="noopener">在地图中查找 ↗</a><a href="${m.official}" target="_blank" rel="noopener">参观信息来源 ↗</a></div><p class="tiny-note">开放与预约可能变化，出发前以馆方公告为准。停留时长为编辑建议。</p></div></div>${GuanwuExperience.museumHighlights(m)}<section class="section audio-section">${head(m.chapters[0]?.audio===false?'留一点时间，读懂这座馆':'让故事，在耳边展开','FIELD NOTES')}<p class="section-description">${m.chapters[0]?.audio===false?'本馆目前提供阅读导览，语音待补充':'AI 合成普通话导览 · 非真人录音 · 非戏曲唱段'}</p><div class="chapter-list">${m.chapters.map((c,i)=>`<button class="chapter" ${c.audio===false?`data-action="transcript" data-id="${id}"`:`data-play="museum:${id}:${i}"`} data-chapter="museum:${id}:${i}"><span class="chapter-number">0${i+1}</span><span><strong>${c.title}</strong><small>${c.audio===false?'阅读手记':i===0?'免费试听':state.member?'已解锁 · 完整导览':'完整导览 · 免费体验解锁'}</small></span><b>${c.audio===false?'↗':i>0&&!state.member?'◇':'▷'}</b></button>`).join('')}</div><button class="text-link transcript-open" data-action="transcript" data-id="${id}">展开全部导览文稿 ↗</button></section><section class="section">${m.artifacts?.length||crafts.some(c=>c.museum===id)?head(m.artifacts?.length?'从这几件文物开始':'先认一门手艺','A CLOSER LOOK'):''}<div class="craft-grid">${m.artifacts?.length?artifacts.filter(a=>a.museum===id).map(artifactCard).join(''):crafts.filter(c=>c.museum===id).map(craftCard).join('')}</div></section><div class="visit-bottom-grid"><section class="visit-tips"><h2>出发前的一点准备</h2><ul>${m.tips.map(t=>`<li>${t}</li>`).join('')}</ul><button class="outline-btn" data-action="download" data-id="${id}">↓ 保存本馆离线导览</button><p class="tiny-note">下载图片与音频到当前浏览器。完整内容需先免费解锁；清理浏览器数据会移除下载。</p><div data-download-status="${id}" role="status"></div></section><section class="reference-panel"><h2>资料与延伸</h2>${sourceLinks(m.sources)}<p class="tiny-note">基础信息核对：${m.checked||GUANWU.updated}。观察提示与导览为观物原创编辑，不代表馆方讲解。</p></section></div>${notePanel('museum:'+id)}`}
function craftPage(id){const c=crafts.find(c=>c.id===id);if(!c)return missing();const m=museums.find(m=>m.id===c.museum);return `${breadcrumbs(c.city+' · '+c.category)}<div class="craft-detail"><div class="craft-visual"><button class="craft-main-image" data-gallery="craft:${id}:0" aria-label="放大${c.title}">${photo(c.cover)}<span>看清一处细节 ＋</span></button>${galleryStrip('craft',c)}<p class="photo-note">${c.label} · <button data-action="credits">摄影与许可 ↗</button></p></div><div class="craft-copy"><div class="eyebrow">THE ART OF MAKING · ${c.category}</div><h1>${c.title}</h1><p class="craft-lead">${c.intro}</p><div class="detail-actions"><button class="solid-btn" data-play="craft:${id}:0">▷ 听工艺讲解</button><button class="outline-btn" data-save="craft:${id}" aria-pressed="${state.saved.includes('craft:'+id)}">${state.saved.includes('craft:'+id)?'♥ 已收藏':'♡ 收藏手艺'}</button></div><p class="article-text">${c.body}</p><h2>不妨这样看</h2><p class="article-text">${c.look}</p><div class="craft-steps"><h2>把工艺拆成三步</h2>${c.steps.map((s,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${['认识材料','理解动作','回看成品'][i]}<b>＋</b></summary><p>${s}</p></details>`).join('')}</div><button class="quiz-invite" data-action="quiz" data-id="${id}"><span>◈</span><div><strong>认一门手艺，收下一枚印记</strong><small>${state.stamps.includes(id)?'已完成 · 可以再温习一次':'一道小问题，把观看留在记忆里'}</small></div>→</button><a class="related-museum" href="#museum/${m.id}">从这里继续：${m.name} ↗</a>${sourceLinks([c.source])}</div></div>${notePanel('craft:'+id)}`}
function journeys(){return GuanwuExperience.journeys()}
function savedPage(){const ms=museums.filter(m=>state.saved.includes('museum:'+m.id)),cs=crafts.filter(c=>state.saved.includes('craft:'+c.id));return `${title('YOUR LITTLE ATLAS','收藏每一次心动','喜欢的手艺、想去的场馆，与自己的观看手记。')}<div class="journal-stats">${[[state.saved.length,'次心动收藏'],[state.plan.length,'座想去的场馆'],[Object.values(state.notes).filter(Boolean).length,'条观看手记'],[state.stamps.length,'枚知识印记']].map(([n,s])=>`<div><b>${n}</b><span>${s}</span></div>`).join('')}</div><section class="section">${head('我的行程','MY JOURNEYS')}${state.plan.length?`<div class="plan-list">${state.plan.map((id,i)=>{const m=museums.find(m=>m.id===id);return m?`<article class="plan-row"><a href="#museum/${id}">${photo(m.cover,'loading="lazy"')}</a><div><small>${m.city} · ${m.kind}</small><h3><a href="#museum/${id}">${m.name}</a></h3><label>计划日期 <input type="date" value="${esc(state.dates[id]||'')}" data-date="${id}" aria-label="${m.name}计划日期"></label></div><div class="plan-actions"><button data-move="${id}:-1" ${i===0?'disabled':''} aria-label="上移${m.name}">↑</button><button data-move="${id}:1" ${i===state.plan.length-1?'disabled':''} aria-label="下移${m.name}">↓</button><button data-plan="${id}" aria-label="移除${m.name}">×</button></div></article>`:''}).join('')}</div><button class="text-link" data-action="copy-plan">复制行程清单 ↗</button>`:'<div class="soft-empty">还没有安排下一站。<a href="#journeys">去选一座博物馆 →</a></div>'}</section>${ms.length?`<section class="section">${head('收藏的场馆','SAVED MUSEUMS')}<div class="museum-grid">${ms.map(museumCard).join('')}</div></section>`:''}${cs.length?`<section class="section">${head('收藏的手艺','SAVED CRAFTS')}<div class="craft-grid">${cs.map(craftCard).join('')}</div></section>`:''}${artifactSection(artifacts.filter(a=>state.saved.includes('artifact:'+a.id)))}<section class="section">${head('观看手记','YOUR OBSERVATIONS')}${Object.entries(state.notes).filter(([,v])=>v.trim()).map(([key,value])=>{const [kind,id]=key.split(':'),item=(kind==='museum'?museums:kind==='artifact'?artifacts:crafts).find(m=>m.id===id);return item?`<article class="journal-note"><a href="#${kind}/${id}">${item.name||item.title} ↗</a><p>${esc(value)}</p><button data-delete-note="${key}" class="text-link">删除手记</button></article>`:''}).join('')||'<div class="soft-empty">在场馆或手艺详情页，留下你的第一条观察。</div>'}</section><section class="section">${head('知识印记','COLLECTED CURIOSITIES')}<div class="stamp-list">${crafts.map(c=>`<button data-action="quiz" data-id="${c.id}" class="stamp ${state.stamps.includes(c.id)?'earned':''}"><span>◈</span><strong>${c.title.split(' · ')[0]}</strong><small>${state.stamps.includes(c.id)?'已认识':'待相遇'}</small></button>`).join('')}</div><p class="tiny-note">知识印记记录答题完成情况，不代表实地到访认证。</p></section>${GuanwuExperience.journal()}${GuanwuRoutePlanner.saved()}`}
function artifactPage(id){const a=artifacts.find(a=>a.id===id);if(!a)return missing();const m=museums.find(m=>m.id===a.museum);return `${breadcrumbs(a.city+' · 馆藏文物')}<div class="craft-detail"><div class="craft-visual"><button class="craft-main-image" data-gallery="artifact:${id}:0" aria-label="放大${a.title}">${photo(a.cover)}<span>细看图像 ＋</span></button>${galleryStrip('artifact',a)}<p class="photo-note">${esc(images[a.cover]?.caption)} · <button data-action="credits">摄影与许可 ↗</button></p></div><div class="craft-copy"><div class="eyebrow">${a.period} · ${a.material}</div><h1>${a.title}</h1><p class="craft-lead">${a.intro}</p><div class="detail-actions"><button class="solid-btn" data-companion>✧ 请伴游讲一讲</button><button class="outline-btn" data-save="artifact:${id}" aria-pressed="${state.saved.includes('artifact:'+id)}">${state.saved.includes('artifact:'+id)?'♥ 已收藏':'♡ 收藏文物'}</button></div><p class="article-text">${a.body}</p><h2>停下来，看这一处</h2><p class="article-text">${a.look}</p><p class="tiny-note">${a.sourceRemarks}</p><a class="related-museum" href="#museum/${m.id}">从这里继续：${m.name} ↗</a>${sourceLinks([a.source])}</div></div>${notePanel('artifact:'+id)}`}
function missing(){return empty('这段故事暂未收录','回到场馆页，再选一处慢慢看。')}
function render(scroll=true){const route=location.hash.slice(1)||'discover',[kind,id]=route.split('/');const tab=['museum','artifact','craft','crafts'].includes(kind)?'collection':kind==='city'?'journeys':['community','post','moderation'].includes(kind)?'community':['collection','journeys','saved'].includes(kind)?kind:'discover';$$('[data-nav]').forEach(a=>{const yes=a.dataset.nav===tab;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#page-label').textContent=({discover:'发现灵感',collection:'博物馆',journeys:'城市漫游',saved:'我的手记',community:'同行交流'})[tab];$('#city-label').textContent=state.city==='全部'?'全部目的地':state.city;$('#app').innerHTML=kind==='community'?GuanwuCommunity.page():kind==='post'?GuanwuCommunity.postPage(id):kind==='moderation'?GuanwuCommunity.moderationPage():kind==='city'?GuanwuExperience.cityPage(id):kind==='inquiry'?GuanwuExperience.inquiryPage(id):kind==='compare'?GuanwuExperience.comparePage(id):kind==='artifact'?artifactPage(id):kind==='museum'?museumPage(id):kind==='craft'?craftPage(id):kind==='crafts'?craftsPage():kind==='collection'?collection():kind==='journeys'?journeys():kind==='saved'?savedPage():home();document.title=($('#app h1')?.textContent||'观物')+' · 观物 GUANWU';if(scroll)window.scrollTo({top:0,behavior:'instant'});if(previousRoute!==route){previousRoute=route;$('#app').focus({preventScroll:true})}syncAudio(player);$('#app').dataset.route=route;GuanwuRoutePlanner.mount(route);GuanwuCommunity.mount(route)}
function toggleSave(key){state.saved=state.saved.includes(key)?state.saved.filter(k=>k!==key):[...state.saved,key];persist('guanwu-saved-v2',state.saved);render(false);toast(state.saved.includes(key)?'已收藏，在“我的手记”等你':'已取消收藏')}
function togglePlan(id){state.plan=state.plan.includes(id)?state.plan.filter(x=>x!==id):[...state.plan,id];persist('guanwu-plan-v2',state.plan);render(false);toast(state.plan.includes(id)?'已加入行程，可安排日期':'已移除这座场馆')}
function membership(){dialog(`<div class="eyebrow">GUANWU · DEEPER STORIES</div><h2 id="modal-title">让好奇，走得更远</h2><p>第一章语音与工艺故事免费开放。体验完整导览，继续听各馆的细看与回望章节。</p><ul><li>5 座非遗场馆的 15 章语音与文稿（新增场馆提供阅读手记）</li><li>下载完整导览，弱网时从容观看</li><li>收藏、手记与知识印记持续保留</li></ul><div class="price">免费体验 <small>当前预览版本</small></div><p class="demo-note">不会扣款。解锁状态仅保存在当前浏览器，真实收费尚未接入。</p><button class="solid-btn" data-action="unlock">${state.member?'已解锁 · 继续探索':'免费体验全部导览 →'}</button>`)}
function quiz(id){const c=crafts.find(c=>c.id===id);if(!c)return;dialog(`<div class="eyebrow">A LITTLE CURIOSITY</div><h2 id="modal-title">认一门手艺</h2><p class="quiz-title">${c.quiz.question}</p><div class="quiz-options">${c.quiz.options.map((o,i)=>`<button data-answer="${id}:${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" role="status"></div>`)}
function answer(value){const [id,index]=value.split(':'),c=crafts.find(c=>c.id===id),yes=Number(index)===c.quiz.answer;$('#quiz-feedback').innerHTML=`<div class="quiz-feedback ${yes?'correct':''}"><strong>${yes?'◈ 收下一枚知识印记':'再想一想，也可以回到图片看看'}</strong><p>${yes?c.quiz.explain:'答案藏在工艺的材料与动作里。可以继续选择。'}</p></div>`;$$('[data-answer]').forEach(b=>{b.classList.remove('wrong');if(b.dataset.answer===value)b.classList.add(yes?'right':'wrong');if(yes)b.disabled=true});if(yes&&!state.stamps.includes(id)){state.stamps.push(id);persist('guanwu-stamps-v2',state.stamps);if(location.hash==='#saved')render(false)}}
function showGallery(value){const [kind,id,n]=value.split(':'),item=(kind==='museum'?museums:kind==='artifact'?artifacts:crafts).find(x=>x.id===id);if(!item||!item.gallery.length)return;state.gallery={kind,id,index:Number(n)||0,ids:item.gallery,scale:1,x:0,y:0};drawGallery();$('#gallery').showModal()}
function drawGallery(){const g=state.gallery,p=images[g.ids[g.index]];if(!p)return;$('#gallery-content').innerHTML=`<div class="gallery-top"><span>${g.index+1} / ${g.ids.length}</span><span>双指或按钮查看细节 · 方向键切换</span></div><div class="gallery-stage"><img id="gallery-image" src="${p.src}" alt="${esc(p.caption)}" draggable="false"><button class="gallery-prev" data-gallery-step="-1" aria-label="上一张图片">‹</button><button class="gallery-next" data-gallery-step="1" aria-label="下一张图片">›</button></div><div class="gallery-bottom"><div><h2>${p.caption}</h2><p>摄影 / ${esc(p.author||'作者见原始来源')} · <a href="${p.source}" target="_blank" rel="noopener">原始来源 ↗</a></p><p><a href="${p.licenseUrl||p.source}" target="_blank" rel="noopener">${p.license}</a> · ${p.changes}</p></div><div class="zoom-controls"><button data-zoom="-.5" aria-label="缩小图片">−</button><span id="zoom-label">100%</span><button data-zoom=".5" aria-label="放大图片">＋</button><button data-zoom="reset" aria-label="重置图片">↺</button></div></div>`;applyZoom()}
function applyZoom(){const g=state.gallery,img=$('#gallery-image');if(!g||!img)return;img.style.transform=`translate(${g.x}px,${g.y}px) scale(${g.scale})`;img.style.cursor=g.scale>1?'grab':'zoom-in';$('#zoom-label').textContent=Math.round(g.scale*100)+'%'}
function galleryStep(delta){const g=state.gallery;if(!g)return;g.index=(g.index+delta+g.ids.length)%g.ids.length;g.scale=1;g.x=g.y=0;drawGallery()}
function time(sec){return Number.isFinite(sec)?Math.floor(sec/60)+':'+Math.floor(sec%60).toString().padStart(2,'0'):'0:00'}
const player=new GuidePlayer($('#guide-audio'),{canPlay:i=>i===0||state.member,onLocked:membership,onError:toast,onChange:p=>syncAudio(p)});
function playGuide(value){const [kind,id,n]=value.split(':'),index=Number(n)||0;if(kind==='museum'){const m=museums.find(m=>m.id===id);if(m&&m.chapters[0]?.audio===false){transcript(id);return}if(m)player.select({id:'museum:'+id,title:m.name,href:'#museum/'+id},m.chapters.map((c,i)=>({title:c.title,text:c.text,src:`assets/audio/${id}-${i}.mp3`})),index)}else{const c=crafts.find(c=>c.id===id);if(c)player.select({id:'craft:'+id,title:c.title,href:'#craft/'+id},[{title:c.title,text:c.audioText,src:`assets/audio/craft-${id}.mp3`}],0)}}
function syncAudio(p){const dock=$('#audio-dock');if(!p?.owner){dock.hidden=true;document.body.classList.remove('has-audio');return}dock.hidden=false;document.body.classList.add('has-audio');const track=p.queue[p.index],key=p.owner.id+':'+p.index;if(dock.dataset.track!==key){dock.dataset.track=key;dock.innerHTML=`<div class="dock-info"><span class="dock-wave">▂▅▃▆▂</span><a href="${p.owner.href}"><strong>${esc(p.owner.title)}</strong><small>${esc(track.title)} · AI 合成</small></a></div><div class="dock-controls"><button data-audio="back" aria-label="后退15秒">↶<small>15</small></button><button class="play-button" data-audio="toggle" aria-label="播放导览">▷</button><button data-audio="forward" aria-label="前进15秒">↷<small>15</small></button></div><div class="dock-progress"><div><span id="audio-time">0:00</span><input id="audio-seek" type="range" min="0" max="100" value="0" step=".1" aria-label="音频播放进度"><span id="audio-duration">0:00</span></div><p id="live-sentence"></p></div><select id="audio-rate" aria-label="播放速度">${[.8,1,1.2,1.5].map(r=>`<option value="${r}">${r}×</option>`).join('')}</select><button data-audio="transcript" aria-label="查看当前讲解文稿">文稿</button><button data-audio="next" aria-label="下一章" ${p.index===p.queue.length-1?'disabled':''}>⇥</button><button class="dock-close" data-audio="close" aria-label="关闭播放器">×</button>`}const playing=!p.audio.paused,b=dock.querySelector('[data-audio="toggle"]');b.textContent=p.loading?'⋯':playing?'Ⅱ':'▷';b.setAttribute('aria-label',playing?'暂停导览':'播放导览');$('#audio-time').textContent=time(p.audio.currentTime);$('#audio-duration').textContent=time(p.audio.duration);if(!p.seeking){$('#audio-seek').max=Number.isFinite(p.audio.duration)?p.audio.duration:100;$('#audio-seek').value=p.audio.currentTime||0}$('#audio-rate').value=p.rate;$('#live-sentence').textContent=p.currentSentence()||'把脚步放慢，让故事继续。';$$('[data-chapter]').forEach(c=>c.classList.toggle('playing',c.dataset.chapter===key&&playing))}
function transcript(id){const m=museums.find(m=>m.id===id);dialog(`<div class="eyebrow">AUDIO TRANSCRIPT · AI 合成导览</div><h2 id="modal-title">${m.name}</h2>${m.chapters.map((c,i)=>`<section class="transcript-chapter"><h3>${c.title}</h3>${c.audio===false||i===0||state.member?`<p>${c.text}</p>${c.audio===false?'':`<button class="text-link" data-action="transcript-play" data-value="museum:${id}:${i}">▷ 播放本章</button>`}`:'<p>体验完整导览后，可查看本章文稿。</p><button class="text-link" data-action="membership">免费体验解锁 →</button>'}</section>`).join('')}`)}
async function downloadGuide(id){if(state.downloadBusy){toast('已有导览正在保存，请稍候');return}if(!state.member){membership();return}if(!('caches'in window)||!navigator.serviceWorker?.controller){toast('离线功能正在准备，稍后重试；请在 HTTPS 或本地预览中打开');return}const m=museums.find(m=>m.id===id);if(!m)return;const cs=crafts.filter(c=>c.museum===id),files=[...new Set([...m.gallery,...cs.flatMap(c=>c.gallery)])].map(k=>images[k]?.src||`assets/heritage/${k}.jpg`);m.chapters.forEach((c,i)=>c.audio!==false&&files.push(`assets/audio/${id}-${i}.mp3`,`assets/audio/${id}-${i}.json`));cs.forEach(c=>files.push(`assets/audio/craft-${c.id}.mp3`,`assets/audio/craft-${c.id}.json`));state.downloadBusy=true;const status=document.querySelector(`[data-download-status="${id}"]`);try{const cache=await caches.open('guanwu-library-v2');for(let i=0;i<files.length;i++){if(status)status.textContent=`正在保存 ${i+1} / ${files.length}…`;const r=await fetch(files[i]);if(!r.ok)throw Error('download');await cache.put(files[i],r)}await cache.put(`__offline__/${id}`,new Response('complete'));if(status)status.textContent='✓ 本馆图片与语音已保存，可离线浏览。';toast('已保存离线导览')}catch{if(status)status.textContent='部分内容未保存，请联网后重试。';toast('下载中断，已保存的内容仍可使用。')}finally{state.downloadBusy=false}}
function showCredits(){dialog(`<div class="eyebrow">PHOTOGRAPHY & SOURCES</div><h2 id="modal-title">每张影像，都有来处</h2><p>场馆实拍与工艺参照图分别标注。署名、原始链接与许可保留在下方；缩放与界面裁切不改变照片本身的许可。</p><div class="credits-list">${Object.values(images).map(p=>`<article><a href="${p.source}" target="_blank" rel="noopener">${esc(p.caption)} ↗</a><p>${esc(p.author)} · <a href="${p.licenseUrl||p.source}" target="_blank" rel="noopener">${p.license}</a><br>${p.changes}</p></article>`).join('')}</div><a class="text-link" href="assets/heritage/credits.json" target="_blank" rel="noopener">查看完整来源记录 ↗</a>`)}
async function copyText(text,message){try{await navigator.clipboard.writeText(text);toast(message)}catch{dialog(`<h2 id="modal-title">复制这段内容</h2><p>长按或选中下方内容复制。</p><textarea class="copy-area" readonly>${esc(text)}</textarea>`);$('.copy-area').select()}}
const actions={membership,
 unlock(){state.member=true;persist('guanwu-demo-member',true);$('#modal').close();render(false);toast('完整导览已免费解锁，未产生扣款')},
 location(){dialog(`<div class="eyebrow">CHOOSE YOUR CITY</div><h2 id="modal-title">下一站，去哪里？</h2><div class="city-list">${['全部',...new Set(museums.map(m=>m.city))].map(c=>`<button data-modal-city="${c}">${c==='全部'?'全部目的地':c}<span>→</span></button>`).join('')}</div>`)},
 search(){state.query='';state.category='全部';location.hash='collection';render();$('#collection-search')?.focus()},
 'reset-search'(){state.city='全部';state.district='全部';state.category='全部';state.museumKind='全部';state.query='';persist('guanwu-city-v2','全部');location.hash='collection';render()},
 'listen-featured'(){playGuide('museum:'+museums[state.hero].id+':0')},profile(){location.hash='saved'},quiz:b=>quiz(b.dataset.id),transcript:b=>transcript(b.dataset.id),
 'transcript-play'(b){$('#modal').close();playGuide(b.dataset.value)},
 'save-note'(b){state.notes[b.dataset.id]=$('#note-input').value.trim();persist('guanwu-notes-v2',state.notes);$('#note-status').textContent='✓ 手记已保存';toast('留住这一次发现')},
 share(){copyText(location.href,'当前页面链接已复制')},
 'copy-plan'(){copyText('观物 · 我的非遗行程\n'+state.plan.map((id,i)=>{const m=museums.find(m=>m.id===id);return `${i+1}. ${m.city} · ${m.name}${state.dates[id]?' · '+state.dates[id]:''}\n${m.address}`}).join('\n\n')+'\n开放及预约请以馆方公告为准。','行程清单已复制')},
 looking(){dialog('<div class="eyebrow">THE ART OF LOOKING</div><h2 id="modal-title">给第一次看展的你</h2><p>先选择一件令你停下来的作品。</p><ul><li>先看轮廓，再看材料。</li><li>放大一处细节，寻找制作的痕迹。</li><li>最后读标签，用信息回答自己的问题。</li><li>若有传承人演示，留意重复的动作与节奏。</li></ul><p>离开时，记下一句自己的发现。无需专业术语，也可以看得很认真。</p>')},
 download:b=>downloadGuide(b.dataset.id),credits:showCredits,
 about(){dialog(`<div class="eyebrow">ABOUT GUANWU</div><h2 id="modal-title">看见手艺，听见城市</h2><p>现在覆盖 ${new Set(museums.map(m=>m.city)).size} 城 ${museums.length} 馆、18 件文物与 8 个工艺专题。原有 5 馆提供 23 段合成语音；其余场馆提供阅读导览。可以在城市漫游中组合多家馆，也可以带着一个问题跨馆对看。DeepSeek 伴游会查询收录资料并给出来源。</p><p>语音为 AI 合成普通话，非真人录音、馆方讲解或戏曲唱段。开放、预约及展演请以馆方当日信息为准。</p><div class="source-links"><button class="text-link" data-action="credits">查看全部摄影与许可 ↗</button><a href="classic/index.html">回看首版 · 中国艺术开放馆藏 ↗</a></div><p class="demo-note">预览体验，会员为免费解锁演示。收藏、手记、行程与离线文件仅存当前设备，暂不跨设备同步。</p>`)},
};
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.go){location.hash=b.dataset.go;return}
 if(b.dataset.city){state.city=b.dataset.city;state.district='全部';persist('guanwu-city-v2',state.city);state.query='';render(false);return}
 if(b.dataset.modalCity){state.city=b.dataset.modalCity;state.query='';persist('guanwu-city-v2',state.city);$('#modal').close();location.hash='collection';render();return}
 if(b.dataset.hero!==undefined){state.hero=Number(b.dataset.hero);$('#hero-slot').innerHTML=hero();return}
 if(b.dataset.museumKind){state.museumKind=b.dataset.museumKind;render(false);return}
 if(b.dataset.category){state.category=b.dataset.category;render(false);return}
 if(b.dataset.save){toggleSave(b.dataset.save);return}if(b.dataset.plan){togglePlan(b.dataset.plan);return}if(b.dataset.play){playGuide(b.dataset.play);return}
 if(b.dataset.gallery){showGallery(b.dataset.gallery);return}if(b.dataset.galleryStep){galleryStep(Number(b.dataset.galleryStep));return}
 if(b.dataset.zoom){const g=state.gallery;if(b.dataset.zoom==='reset'){g.scale=1;g.x=g.y=0}else{g.scale=Math.max(1,Math.min(4,g.scale+Number(b.dataset.zoom)));if(g.scale===1)g.x=g.y=0}applyZoom();return}
 if(b.dataset.answer){answer(b.dataset.answer);return}
 if(b.dataset.move){const [id,n]=b.dataset.move.split(':'),i=state.plan.indexOf(id),to=i+Number(n);if(to>=0&&to<state.plan.length){[state.plan[i],state.plan[to]]=[state.plan[to],state.plan[i]];persist('guanwu-plan-v2',state.plan);render(false)}return}
 if(b.dataset.deleteNote){dialog(`<h2 id="modal-title">删除这条手记？</h2><p>删除后无法恢复。</p><button class="solid-btn" data-confirm-delete="${b.dataset.deleteNote}">确认删除这条手记</button>`);return}
 if(b.dataset.confirmDelete){delete state.notes[b.dataset.confirmDelete];persist('guanwu-notes-v2',state.notes);$('#modal').close();render(false);return}
 if(b.dataset.audio){({toggle:()=>player.toggle(),back:()=>player.skip(-15),forward:()=>player.skip(15),close:()=>player.close(),next:()=>player.load(player.index+1,true),transcript:()=>dialog(`<div class="eyebrow">AUDIO TRANSCRIPT · AI 合成</div><h2 id="modal-title">${esc(player.queue[player.index].title)}</h2><p>${esc(player.queue[player.index].text)}</p>`)})[b.dataset.audio]?.();return}
 actions[b.dataset.action]?.(b);
});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=$('#collection-search').value.trim();$('#search-results').innerHTML=searchResults()}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='collection-search'){state.query=t.value.trim();$('#search-results').innerHTML=searchResults()}if(t.id==='audio-seek'){player.seeking=true;$('#audio-time').textContent=time(Number(t.value))}if(t.dataset.note){state.notes[t.dataset.note]=t.value;persist('guanwu-notes-v2',state.notes);$('#note-status').textContent='✓ 已自动保存 · 当前浏览器'}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='museum-district'){state.district=t.value;$('#search-results').innerHTML=searchResults()}if(t.id==='audio-seek'){player.seeking=false;player.seek(t.value)}if(t.id==='audio-rate')player.setRate(t.value);if(t.dataset.date){state.dates[t.dataset.date]=t.value;persist('guanwu-dates-v2',state.dates);toast('行程日期已保存')}});
$('.close-dialog').onclick=()=>$('#modal').close();$('.gallery-close').onclick=()=>$('#gallery').close();
for(const d of [$('#modal'),$('#gallery')])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
document.addEventListener('keydown',e=>{if(!$('#gallery').open)return;if(e.key==='ArrowRight'){e.preventDefault();galleryStep(1)}if(e.key==='ArrowLeft'){e.preventDefault();galleryStep(-1)}});
let drag=null,pinch=null;const pointers=new Map();
$('#gallery').addEventListener('pointerdown',e=>{if(e.target.id!=='gallery-image')return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});e.target.setPointerCapture(e.pointerId);const g=state.gallery;if(pointers.size===2){const ps=[...pointers.values()];pinch={distance:Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y),scale:g.scale}}else drag={x:e.clientX,y:e.clientY,ox:g.x,oy:g.y}});
$('#gallery').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const g=state.gallery;if(pointers.size===2&&pinch){const ps=[...pointers.values()];g.scale=Math.max(1,Math.min(4,pinch.scale*Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y)/pinch.distance));applyZoom()}else if(drag&&g.scale>1){g.x=Math.max(-400,Math.min(400,drag.ox+e.clientX-drag.x));g.y=Math.max(-400,Math.min(400,drag.oy+e.clientY-drag.y));applyZoom()}});
for(const evt of ['pointerup','pointercancel'])$('#gallery').addEventListener(evt,e=>{pointers.delete(e.pointerId);drag=null;pinch=null});
window.addEventListener('hashchange',()=>render());window.addEventListener('offline',()=>toast('已离线，已保存的导览仍可继续使用。'));window.addEventListener('online',()=>toast('网络已恢复'));
async function init(){try{const r=await fetch('assets/heritage/credits.json');if(!r.ok)throw Error('credits');images={...await r.json(),...GUANWU_EXPANSION.images,...GUANWU_CITY_MUSEUMS.images,...GUANWU_BEIJING_MUSEUMS.images}}catch{toast('部分图片来源信息尚未加载，请联网后重试。')}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}
init();
